(() => {
const KEY='iot-systems-design-session2-v3';
const activities=['Describe the conversations','Draw a message choreography','Build the stack by responsibility','Discover network and transport pieces','Discover application exchange protocols','Make the exchange interoperable','Compose complete stacks','Choose the delivery semantics','Stress-test the exchange'];
const defaultState=()=>({screen:0,frontier:0,maxUnlockedScreen:0,conversations:{},actors:[null,null,null,null],messages:[],stackRoles:{},networkDetective:{},appPatterns:{},claims:{},composeCase:'a',compositions:{a:{},b:{}},composeValid:{a:false,b:false},interopFields:[],naming:{},interopRationale:'',campusChoice:'',campusRationale:'',incident:'',failureMeaning:'',failureLayer:'',failureRevision:'',deliveryCases:{},deliveryMechanisms:{},deliveryRationale:'',stopChallenges:{},conceptUnlocks:{},recall:{},adaptiveDepth:{},challengeProgress:{}});
let state=load();
let selectedActor=null, selectedResp=null, selectedProto=null, selectedDeliveryMechanism=null;
const screens=[...document.querySelectorAll('.activity-screen')], stepper=document.getElementById('stepper');
function load(){try{return {...defaultState(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return defaultState()}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));document.getElementById('saveState').textContent='Saved on this device'}catch{document.getElementById('saveState').textContent='Local save unavailable'}renderDrawer()}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1300)}
const SCREEN_TO_ACTIVITY=[0,0,1,1,2,2,3,4,5,5,6,6,7,7,8,8,8];
function screenToActivity(s){return SCREEN_TO_ACTIVITY[s]??8}
const ACTIVITY_ENTRY=[0,2,4,6,7,8,10,12,14];
state.maxUnlockedScreen=Math.max(Number(state.maxUnlockedScreen)||0,Number(state.screen)||0,ACTIVITY_ENTRY[Math.min(Number(state.frontier)||0,8)]||0);
function renderStepper(){const current=screenToActivity(state.screen),max=Number(state.maxUnlockedScreen)||0;stepper.innerHTML=activities.map((x,i)=>{const unlocked=ACTIVITY_ENTRY[i]<=max;return `<button class="step-dot ${unlocked&&i<screenToActivity(max)?'done':''} ${i===current?'active':''}" ${unlocked?'':'disabled'} data-jump="${ACTIVITY_ENTRY[i]}"><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span></button>`}).join('');stepper.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>show(+b.dataset.jump,false))}
function renderHistoryNav(){const nav=document.getElementById('historyNav');if(!nav)return;const max=Number(state.maxUnlockedScreen)||0,reviewing=state.screen<max;if(!reviewing){nav.hidden=true;nav.innerHTML='';return}nav.hidden=false;nav.innerHTML=`<div class="history-status"><strong>Review mode</strong><span>You are revisiting completed work. Future information stays gated.</span></div><button type="button" class="btn" id="returnToCurrent">Return to current mission →</button>`;document.getElementById('returnToCurrent').onclick=()=>show(max,false)}
function show(n,advance=true){if(n<0||n>=screens.length)return;const max=Number(state.maxUnlockedScreen)||0;if(!advance&&n>max){toast('That stage is still locked');return}if(advance&&n>max)state.maxUnlockedScreen=n;state.screen=n;state.frontier=Math.max(Number(state.frontier)||0,screenToActivity(Number(state.maxUnlockedScreen)||n));document.body.classList.toggle('past-intro',n>=2);screens.forEach((s,i)=>s.hidden=i!==n);renderStepper();renderHistoryNav();renderSnapshots();save();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>show(+b.dataset.next));
document.querySelectorAll('[data-review-screen]').forEach(b=>b.onclick=()=>show(+b.dataset.reviewScreen,false));


const conceptDefs={
 interaction:{
  title:'Interaction patterns before protocols',
  bridge:'Your four cases differed in initiator, receiver set, reply expectation and timing. Those differences describe the service conversation before any protocol implementation is chosen.',
  formal:'An <strong>interaction pattern</strong> captures who talks to whom and how: request/response, command/acknowledgement, publish/subscribe, observe/notify, event notification or streaming. Direct and broker-mediated exchanges create different coupling.',
  carry:'For a new service, state the <strong>service need → interaction pattern</strong> first. Only then ask which application protocol can implement it.',
  fieldSummary:'Describe the service conversation before choosing a protocol.',
  fieldKeep:'Request/response · command/ack · publish/subscribe · observe/notify · event notification · streaming. Also ask one-to-one vs one-to-many and direct vs broker-mediated.',
  reference:[['Decision cues',['initiator','receiver set','reply expected?','periodic / event-driven']],['Core distinction',['pattern = service semantics','protocol = one implementation']]],
  tags:['service need first','coupling','asynchrony']
 },
 choreography:{
  title:'Topology is not choreography',
  bridge:'A static set of nodes did not tell you which message starts the exchange, whether an intermediary fans out data, or whether a reply is required.',
  formal:'A <strong>topology</strong> describes where communication paths exist. A <strong>message choreography</strong> describes actors, ordered messages and their roles over time. Useful actor roles include producer, consumer, gateway/proxy and broker.',
  carry:'Draw the exchange when order, coupling or intermediary behaviour matters. Label messages by meaning: telemetry, query/response, command/acknowledgement, event/notification.',
  fieldSummary:'Use a message sequence to expose order, coupling and intermediary roles that a topology hides.',
  fieldKeep:'Producer/consumer/broker/gateway are roles, not interchangeable labels. A broker mediates message distribution; a gateway may forward, translate or process.',
  reference:[['Actors',['producer / sensor','consumer / service','gateway / proxy','broker']],['Messages',['telemetry','query / response','command / acknowledgement','event / notification']]],
  tags:['actors','ordered messages','topology ≠ behaviour']
 },
 stack:{
  title:'Stack by responsibility',
  bridge:'The placements showed that communication is not one undifferentiated “network” function. Different responsibilities act at different scopes and can be implemented by different protocols or suites.',
  formal:'Use the working model <strong>Application exchange → Transport → Network → Adaptation → Local link</strong>. Application defines resources/topics and operations; transport offers ports/endpoints and datagram/stream behaviour; network addresses/routes packets; adaptation makes IP practical on constrained links; the local link moves immediate-hop frames.',
  carry:'Compare technologies <strong>within the responsibility they solve</strong>. A named suite such as Thread can span several rows, so protocol names do not always map one-to-one onto layers.',
  fieldSummary:'A stack is an ordered composition of responsibilities, not a list of protocol names.',
  fieldKeep:'Application: meaning/resources/topics · Transport: ports + datagram/stream · Network: IP addressing/routing · Adaptation: constrained-link IP support · Link: immediate-hop frames/medium.',
  reference:[['Working rows',['Application exchange','Transport','Network','Adaptation','Local link']],['Boundary examples',['topics/resources → application','ports → transport','6LoWPAN → adaptation']]],
  tags:['responsibility before name','scope','suite can span rows']
 },
 interoperability:{
  title:'Protocol ≠ semantic interoperability',
  bridge:'A receiver can obtain {"value":812} perfectly and still not know the phenomenon, unit, source, timestamp or context. Likewise, IP addresses, ports, hostnames, resource paths and MQTT topics identify different things.',
  formal:'<strong>Protocol interoperability</strong> lets systems exchange messages. <strong>Semantic interoperability</strong> requires enough shared structure, identifiers and meaning to interpret what those messages represent. Think <strong>bytes → syntax/schema → context → shared meaning</strong>.',
  carry:'For measurements, make phenomenon, value/unit, source, timestamp, location/context and quality/validity explicit when needed. Keep communication endpoints separate from application resource/topic identifiers.',
  fieldSummary:'Successful message transport does not imply shared meaning.',
  fieldKeep:'Measurement context: phenomenon · value/unit · source · timestamp · location · quality. Endpoint identifiers: hostname · IP address · port. Application identifiers: resource URI/path · MQTT topic.',
  reference:[['Representation',['SenML · RFC 8428']],['Discovery',['CoRE Link Format · RFC 6690']],['Interface metadata',['W3C WoT Thing Description']]],
  tags:['bytes ≠ meaning','naming matters','shared model']
 },
 composition:{
  title:'Compose across responsibilities',
  bridge:'MQTT, TCP, Thread and Wi-Fi looked comparable only when abstraction levels were ignored. Your two stacks showed that several of them can coexist because they solve different responsibilities.',
  formal:'Compare candidates <strong>within one responsibility</strong>, then compose compatible pieces across the stack. MQTT, CoAP and HTTP are application protocols; TCP/UDP are transports; IPv6 is network-layer; 6LoWPAN is adaptation; IEEE 802.15.4/Wi-Fi provide local-link functions. Thread is an IPv6-based IoT networking suite rather than a peer substitute for TCP or MQTT.',
  carry:'When reading an architecture, ask what each name contributes and what it expects underneath. A technically valid stack can still be wrong for the service semantics or delivery guarantee.',
  fieldSummary:'Protocol selection is a composition problem across abstraction levels.',
  fieldKeep:'MQTT: brokered pub/sub · CoAP: constrained resource exchange · HTTP: request/response web semantics · TCP: reliable in-order byte stream · UDP: datagrams · IPv6: addressing/routing · 6LoWPAN: adaptation · Thread: IPv6 IoT networking suite.',
  reference:[['Application examples',['MQTT','CoAP','HTTP']],['Networking below',['TCP / UDP','IPv6','6LoWPAN','Thread','IEEE 802.15.4 / Wi-Fi']],['Also recognise',['WebSocket','AMQP','DDS','LwM2M']]],
  tags:['compare within role','compose across roles','dependencies']
 },
 delivery:{
  title:'Delivery guarantees have a scope',
  bridge:'The same word “reliable” hid several different claims: bytes arrive, a protocol message is delivered, an application operation occurs once, state survives disconnection, or a physical effect actually happens.',
  formal:'A guarantee must name its <strong>object and scope</strong>. TCP provides reliable in-order bytes; MQTT QoS defines MQTT message-delivery behaviour; CoAP Confirmable messages add acknowledgement/retransmission; application idempotence/deduplication controls duplicate effects; persistence handles absence; physical feedback observes the real outcome.',
  carry:'Write <strong>service requirement → guaranteed object/scope → mechanism → residual failure</strong>. No single “reliable protocol” automatically gives end-to-end correctness.',
  fieldSummary:'“Reliable” is meaningful only after the guaranteed object and scope are explicit.',
  fieldKeep:'MQTT QoS 0: at most once · QoS 1: at least once · QoS 2: exactly once at MQTT message-delivery scope. TCP: reliable in-order byte stream. CoAP CON: ACK + retransmission. Application: idempotence/dedup. Physical: state feedback.',
  reference:[['Service targets',['ambient sample → best effort may suffice','critical alert → at least-once message delivery','command → prevent duplicate operation effect','temporary disconnect → persistence / replay']],['Scope ladder',['transport','application protocol','application/system','intermediary state','physical loop']]],
  tags:['object + scope','end to end','residual failure']
 },
 failure:{
  title:'Trace failures end to end',
  bridge:'A lower layer can satisfy its own contract while the service still fails later. Reliable byte delivery, for example, does not prove that an operation executed once or that a physical actuator moved.',
  formal:'A strong failure analysis follows <strong>required guarantee → object/scope → mechanism → observed failure → revision → residual risk</strong>. This prevents vague diagnoses such as “the network failed” when the real issue is application semantics, intermediary state or physical feedback.',
  carry:'For every revision, state which guarantee it restores and what failure remains possible. Retries, idempotence, buffering, freshness, availability and state feedback solve different problems.',
  fieldSummary:'End-to-end correctness is a chain of scoped guarantees, not a property inherited from one protocol.',
  fieldKeep:'Trace: required guarantee · scope/object · mechanism · observed failure · revision · residual risk. Ask which earlier claims still held even though the service outcome was wrong.',
  reference:[['Application owns',['operation semantics','idempotence / deduplication','freshness / correlation']],['System dependencies',['broker/service availability','sleep schedules','buffering / store-and-forward','physical feedback']]],
  tags:['failure trace','evidence','revision']
 }
};
const conceptOrder=['interaction','choreography','stack','interoperability','composition','delivery','failure'];
const stopChallengeDefs={
 interaction:{title:'Receiver set changes later',prompt:'An alert must reach two services that did not exist when the sensor firmware was written. Which conversation structure handles that change naturally, and what coupling does it remove?'},
 choreography:{title:'Same topology, different behaviour',prompt:'The dashboard disappears, but storage and alerting still need telemetry. Which choreography survives that change, and which actor was unnecessarily coupled to the producer?'},
 stack:{title:'Reliability can move upward',prompt:'If an application uses UDP, does that mean acknowledgements or retries are impossible? Which responsibility could add them, and what would still remain different from TCP?'},
 interoperability:{title:'Perfect transport, wrong meaning',prompt:'Two sensors publish {"value":25}. One means 25 °C and the other 25 %RH. Every packet and protocol exchange succeeds. Is the system interoperable?'},
 composition:{title:'Wrong comparison',prompt:'A team writes “Thread + TCP + MQTT” as three alternatives. What is wrong with the comparison before you discuss performance or energy?'},
 delivery:{title:'Exactly-once message, duplicate effect',prompt:'MQTT delivers a command exactly once to a client, but the client crashes after actuating and before recording completion. Can an upstream retry still duplicate the physical effect?'},
 failure:{title:'The reliable layer did its job',prompt:'TCP delivers command bytes reliably. The application times out waiting for its own response and retries after the first operation already happened. Which guarantee failed, and which mechanism should change?'}
};
function renderStopRitual(){
 document.querySelectorAll('[data-stop-challenge]').forEach(host=>{const id=host.dataset.stopChallenge,d=stopChallengeDefs[id],shown=!!state.stopChallenges?.[id];if(!d)return;host.innerHTML=`<div class="ritual-card challenge"><span class="ritual-kicker">3 · Challenge</span><strong>${d.title}</strong>${shown?`<p>${d.prompt}</p>`:`<p>Reveal the counterexample when your teacher asks. Use it to test whether the class rule is too broad.</p><button type="button" class="btn reveal-stop-challenge" data-id="${id}">Reveal teacher challenge</button>`}</div>`});
 document.querySelectorAll('.reveal-stop-challenge').forEach(b=>b.onclick=()=>{state.stopChallenges={...(state.stopChallenges||{}),[b.dataset.id]:true};save();renderStopRitual()});
 document.querySelectorAll('[data-concept]').forEach(host=>{const id=host.dataset.concept,d=conceptDefs[id],unlocked=!!state.conceptUnlocks?.[id];if(!d)return;host.innerHTML=`<div class="ritual-card unlock ${unlocked?'unlocked':''}"><span class="ritual-kicker">4 · Unlock</span>${unlocked?`<strong>${d.title}</strong><div class="unlock-sequence"><section><span>From your discussion</span><p>${d.bridge}</p></section><section><span>Formalise it</span><p>${d.formal}</p></section><section class="carry"><span>Carry it forward</span><p>${d.carry}</p></section></div><div class="unlock-tags">${d.tags.map(x=>`<span>${x}</span>`).join('')}</div>`:`<strong>Consolidate what the class just discovered.</strong><p>Do not leave the STOP with only examples. Connect the discussion and counterexample to the formal rule you will reuse.</p><button type="button" class="btn primary unlock-concept" data-id="${id}">Consolidate what we keep</button>`}</div>`});
 document.querySelectorAll('.unlock-concept').forEach(b=>b.onclick=()=>{state.conceptUnlocks={...(state.conceptUnlocks||{}),[b.dataset.id]:true};save();renderStopRitual();renderFieldGuide();updateStopNextButtons()});
 updateStopNextButtons();
}
function updateStopNextButtons(){document.querySelectorAll('[data-requires-unlock]').forEach(b=>b.disabled=!state.conceptUnlocks?.[b.dataset.requiresUnlock])}
function renderFieldGuide(){const count=conceptOrder.filter(id=>state.conceptUnlocks?.[id]).length,btn=document.getElementById('fieldGuideBtn'),counter=document.getElementById('fieldGuideCount'),host=document.getElementById('fieldGuideContent');if(btn)btn.hidden=count===0;if(counter)counter.textContent=`${count}/7`;if(!host)return;host.innerHTML=`<div class="field-guide-progress"><strong>${count} / 7 concepts consolidated</strong><span>Compact reference maps unlocked after class discussion.</span></div>${conceptOrder.map((id,i)=>{const d=conceptDefs[id],on=!!state.conceptUnlocks?.[id];return `<section class="guide-entry ${on?'':'locked'}"><span class="guide-number">${i+1}</span><div>${on?`<strong>${d.title}</strong><p>${d.fieldSummary}</p><div class="guide-keep">${d.fieldKeep}</div><div class="guide-reference">${d.reference.map(([label,items])=>`<div><b>${label}</b><span>${items.join(' · ')}</span></div>`).join('')}</div>`:`<strong>Concept locked</strong><p>Complete the corresponding STOP discussion first.</p>`}</div></section>`}).join('')}`}

const challengeIds=['stack','semantics','composition','delivery'];
function renderExpertProgress(){const n=challengeIds.filter(id=>state.challengeProgress?.[id]).length;const pill=document.getElementById('expertProgress');if(pill){pill.textContent=`Depth trail ${n}/4`;pill.classList.toggle('active',n>0)}const finish=document.getElementById('expertFinish');if(finish)finish.innerHTML=`<span>Optional depth trail</span><strong>${n} / 4 explored</strong><small>Challenge routes use the same concepts with less guidance. They are optional and not graded.</small>`}
const adaptiveDepthDefs={
 stack:{host:'#depthStack',title:'One named suite spans several rows.',problem:'A future networking suite provides constrained-link adaptation, IPv6 connectivity, mesh routing and network management. Your five-row reasoning model seems to demand one box. Represent the suite without pretending it solves only one responsibility, and explain how your representation still supports comparison with other candidates.',supports:['Separate the reasoning model from the implementation package: one suite may implement several distinct responsibilities.','Map each concrete function to the responsibility it serves instead of forcing the suite name into one row.','Test your model: can you still compare its transport or application choices independently from the networking suite?'],placeholder:'The suite spans… I would represent it as… This preserves comparison because…'},
 semantics:{host:'#depthSemantics',title:'Same phenomenon, incompatible models.',problem:'Two devices both measure temperature. One sends {"v":21.4,"u":"Cel"}; the other sends {"temperature":294.55,"unit":"K"}. Both payloads are valid and delivered successfully. Define the minimum mapping or shared description required so one consumer can interpret both without device-specific hard-coding.',supports:['Start from the phenomenon itself, then separate value representation from shared meaning.','Identify which metadata must be normalized: phenomenon identifier, unit, source, timestamp/context when relevant.','A strong answer distinguishes schema translation from semantic agreement and names where that mapping could live.'],placeholder:'The shared meaning is… I would normalize… The mapping belongs… Delivery alone is insufficient because…'},
 composition:{host:'#depthComposition',title:'Could MQTT run over Thread?',problem:'A colleague says “we must choose between MQTT and Thread.” Decide whether that comparison is well formed. If it is not, build one plausible responsibility chain showing how the two names could coexist, and state what additional transport/application assumptions are required.',supports:['Ask which responsibility each name solves before asking whether they compete.','Thread supplies IPv6-oriented networking functions; MQTT is an application messaging protocol and expects a transport beneath it.','A strong answer names the missing transport assumption and avoids claiming every combination is automatically suitable for the service.'],placeholder:'The comparison is / is not well formed because… One plausible chain is… It still depends on…'},
 delivery:{host:'#depthDelivery',title:'Close the duplicate-operation crash window.',problem:'A command may be retried. The actuator must not execute the same logical operation twice, even if the client crashes after actuation. Design the minimum end-to-end mechanism using operation identity, durable deduplication state and physical feedback. Then name one crash window or residual failure that still remains.',supports:['Locate the durable state: where is the operation identifier remembered, and when relative to actuation?','Separate command acceptance from physical effect. They require different evidence.','A strong answer states the ordering/atomicity assumption and one residual failure that the mechanism does not eliminate.'],placeholder:'Operation ID… Deduplication state… Ordering relative to actuation… Physical feedback… Residual failure…'}
};
function depthEntry(id){state.adaptiveDepth=state.adaptiveDepth||{};if(!state.adaptiveDepth[id])state.adaptiveDepth[id]={support:0,response:''};return state.adaptiveDepth[id]}
function escapeHtml(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function renderAdaptiveDepth(){
 Object.entries(adaptiveDepthDefs).forEach(([id,d])=>{
  const host=document.querySelector(d.host);if(!host)return;
  const x=depthEntry(id),support=Math.max(0,Math.min(3,Number(x.support)||0)),complete=(x.response||'').trim().length>=30;
  host.innerHTML=`<div class="depth-intro"><div><strong>${d.title}</strong><p>Try the open problem first. Open support only when it genuinely helps.</p></div><span class="depth-rule">Beat the scaffold</span></div><div class="depth-problem"><strong>Open problem</strong><p>${d.problem}</p></div><div class="depth-supports">${d.supports.map((h,i)=>{const n=i+1,shown=support>=n,enabled=n===1||support>=n-1;return `<button type="button" class="depth-support-btn ${shown?'used':''}" data-depth-support="${id}" data-level="${n}" ${enabled?'':'disabled'}>${shown?'✓ ':''}Support ${n}</button>`}).join('')}</div><div class="depth-support-reveal">${d.supports.slice(0,support).map((h,i)=>`<div><b>Support ${i+1}</b> · ${h}</div>`).join('')}</div><label class="depth-response"><span class="label">Your reasoning</span><textarea data-depth-response="${id}" maxlength="900" placeholder="${escapeHtml(d.placeholder)}">${escapeHtml(x.response||'')}</textarea></label><div class="depth-status"><span>Support used: <strong>${support}/3</strong>${complete&&support===0?' · solved without support':''}</span><span class="${complete?'depth-complete':''}">${complete?'Depth route explored':'Write a short defended answer to complete this route.'}</span></div>`;
  const badge=host.closest('.adaptive-depth')?.querySelector('.depth-badge');
  if(badge)badge.textContent=complete?`Explored · ${support}/3 support`:`${support}/3 support`;
 });
 document.querySelectorAll('[data-depth-support]').forEach(b=>{
  b.onclick=()=>{const x=depthEntry(b.dataset.depthSupport);x.support=Math.max(Number(x.support)||0,+b.dataset.level);save();renderAdaptiveDepth()};
 });
 document.querySelectorAll('[data-depth-response]').forEach(t=>{
  t.oninput=()=>{
   const id=t.dataset.depthResponse,x=depthEntry(id);x.response=t.value;
   if(t.value.trim().length>=30)state.challengeProgress={...(state.challengeProgress||{}),[id]:true};
   else if(state.challengeProgress?.[id]){const cp={...(state.challengeProgress||{})};delete cp[id];state.challengeProgress=cp}
   save();renderExpertProgress();
   const status=t.closest('.adaptive-depth-body')?.querySelector('.depth-status span:last-child');
   if(status){const done=t.value.trim().length>=30;status.textContent=done?'Depth route explored':'Write a short defended answer to complete this route.';status.classList.toggle('depth-complete',done)}
   const badge=t.closest('.adaptive-depth')?.querySelector('.depth-badge');
   if(badge)badge.textContent=t.value.trim().length>=30?`Explored · ${depthEntry(id).support||0}/3 support`:`${depthEntry(id).support||0}/3 support`;
  };
 });
 renderExpertProgress();
}

const convoCases=[
{id:'telemetry',k:'A',title:'Periodic telemetry',copy:'Amina needs each sensor to report temperature, humidity, CO₂ and noise every minute.'},
{id:'query',k:'B',title:'Read current value',copy:'Sam is on site and asks one sensor for its current CO₂ value now.'},
{id:'alert',k:'C',title:'Abnormal-condition alert',copy:'Amina requires a high CO₂ condition to reach every interested monitoring service quickly.'},
{id:'config',k:'D',title:'Configuration command',copy:'Leila needs a new sampling interval sent to a selected group of sensors.'}
];
const opts={init:['Device','Service / user','Either'],recv:['One known peer','Several known peers','Interested receivers'],reply:['Yes','No','Maybe / depends'],time:['Occasional','Periodic','Event-driven']};
function renderConversations(){const host=document.getElementById('conversationGrid');host.innerHTML=convoCases.map(c=>{const d=state.conversations[c.id]||{};const sel=(key,label)=>`<label>${label}<select data-convo="${c.id}" data-key="${key}"><option value="">Choose…</option>${opts[key].map(o=>`<option ${d[key]===o?'selected':''}>${o}</option>`).join('')}</select></label>`;return `<article class="conversation-card"><span class="case-kicker">Case ${c.k}</span><h3>${c.title}</h3><p>${c.copy}</p><div class="question-row">${sel('init','Who initiates?')}${sel('recv','Who receives?')}${sel('reply','Reply expected?')}${sel('time','When?')}</div></article>`}).join('');host.querySelectorAll('select').forEach(s=>s.onchange=()=>{const id=s.dataset.convo,key=s.dataset.key;state.conversations[id]=state.conversations[id]||{};state.conversations[id][key]=s.value;save();updateGates()})}

const actors=['Sensor','Gateway','Broker','Processing service','Database','Dashboard','Operator'];
function renderChoreo(){document.getElementById('actorPalette').innerHTML=actors.map(a=>`<div class="actor-chip ${selectedActor===a?'selected':''}" draggable="true" data-actor="${a}">${a}</div>`).join('');const lanes=document.getElementById('actorLanes');lanes.innerHTML=state.actors.map((a,i)=>`<div class="actor-lane ${a?'filled':''}" data-lane="${i}">${a||`Drop actor ${i+1}`}</div>`).join('');document.querySelectorAll('.actor-chip').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.actor);x.onclick=()=>{selectedActor=selectedActor===x.dataset.actor?null:x.dataset.actor;renderChoreo()}});lanes.querySelectorAll('.actor-lane').forEach(l=>{l.ondragover=e=>{e.preventDefault();l.classList.add('dragover')};l.ondragleave=()=>l.classList.remove('dragover');l.ondrop=e=>{e.preventDefault();l.classList.remove('dragover');state.actors[+l.dataset.lane]=e.dataTransfer.getData('text/plain');selectedActor=null;save();renderChoreo();updateGates()};l.onclick=()=>{if(selectedActor){state.actors[+l.dataset.lane]=selectedActor;selectedActor=null;save();renderChoreo();updateGates()}}});const placed=state.actors.filter(Boolean);const makeOpts=placed.map(a=>`<option>${a}</option>`).join('');document.getElementById('msgFrom').innerHTML=makeOpts;document.getElementById('msgTo').innerHTML=makeOpts;document.getElementById('messageList').innerHTML=state.messages.map((m,i)=>`<div class="message"><strong>${m.from}</strong><b>→</b><strong>${m.to}</strong><span>${m.label}</span><button data-del-msg="${i}">×</button></div>`).join('');document.querySelectorAll('[data-del-msg]').forEach(b=>b.onclick=()=>{state.messages.splice(+b.dataset.delMsg,1);save();renderChoreo();updateGates()})}
document.getElementById('addMessage').onclick=()=>{const from=document.getElementById('msgFrom').value,to=document.getElementById('msgTo').value,label=document.getElementById('msgLabel').value.trim();if(!from||!to||from===to||!label)return toast('Place actors and label the message');state.messages.push({from,to,label});document.getElementById('msgLabel').value='';save();renderChoreo();updateGates()};
document.getElementById('choreoScenario').onchange=e=>{state.choreoScenario=e.target.value;save()};

const layers=[['application','Application exchange'],['transport','Transport'],['network','Network'],['adaptation','Adaptation'],['link','Local link']];
const responsibilities=[
{id:'meaning',text:'Define message meaning: read, publish, subscribe, command',correct:'application'},
{id:'stream',text:'Offer datagrams or an ordered reliable byte stream',correct:'transport'},
{id:'address',text:'Address and route packets across IP networks',correct:'network'},
{id:'compress',text:'Compress / adapt IPv6 for a constrained local link',correct:'adaptation'},
{id:'frames',text:'Move local frames over the immediate medium',correct:'link'},
{id:'ports',text:'Identify end-to-end application endpoints with ports',correct:'transport'},
{id:'resource',text:'Name resources/topics and define application operations',correct:'application'}
];
function placeResp(rid,layer){Object.keys(state.stackRoles).forEach(k=>state.stackRoles[k]=(state.stackRoles[k]||[]).filter(x=>x!==rid));state.stackRoles[layer]=state.stackRoles[layer]||[];state.stackRoles[layer].push(rid);selectedResp=null;save();renderRoleStack();updateGates()}
function renderRoleStack(){const placed=new Set(Object.values(state.stackRoles).flat());document.getElementById('responsibilityPalette').innerHTML=responsibilities.filter(r=>!placed.has(r.id)).map(r=>`<div class="resp-chip ${selectedResp===r.id?'selected':''}" draggable="true" data-resp="${r.id}">${r.text}</div>`).join('');document.getElementById('stackSlots').innerHTML=layers.map(([id,name])=>`<div class="stack-slot" data-layer="${id}"><strong>${name}</strong><div class="slot-items">${(state.stackRoles[id]||[]).map(rid=>{const r=responsibilities.find(x=>x.id===rid);return `<span class="slot-item" data-rid="${rid}">${r.text}</span>`}).join('')}</div></div>`).join('');document.querySelectorAll('.resp-chip').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.resp);x.onclick=()=>{selectedResp=selectedResp===x.dataset.resp?null:x.dataset.resp;renderRoleStack()}});document.querySelectorAll('.stack-slot').forEach(s=>{s.ondragover=e=>{e.preventDefault();s.classList.add('dragover')};s.ondragleave=()=>s.classList.remove('dragover');s.ondrop=e=>{e.preventDefault();s.classList.remove('dragover');const rid=e.dataTransfer.getData('text/plain');placeResp(rid,s.dataset.layer)};s.onclick=()=>{if(selectedResp)placeResp(selectedResp,s.dataset.layer)}})}

const networkCards=[
{id:'ipv6',clue:'Provides IP addressing and packet forwarding across interconnected networks.',name:'IPv6',role:'Network',detail:'IPv6 defines the network-layer packet format and addressing used by Thread and other IP networks.'},
{id:'6lowpan',clue:'Makes IPv6 practical on constrained links by compressing headers and supporting adaptation over small frames.',name:'6LoWPAN',role:'Adaptation',detail:'6LoWPAN adapts IPv6 to constrained IEEE 802.15.4-style networks.'},
{id:'tcp',clue:'Offers an ordered, reliable stream of bytes between endpoints.',name:'TCP',role:'Transport',detail:'TCP is a transport-layer reliable byte-stream protocol; it does not define application message meaning.'},
{id:'udp',clue:'Offers datagrams with minimal mechanism; delivery, ordering and duplicate protection are not guaranteed by the protocol.',name:'UDP',role:'Transport',detail:'UDP is a datagram transport. Applications can add their own reliability semantics when needed.'},
{id:'thread',clue:'Builds a low-power IPv6 mesh on IEEE 802.15.4, with 6LoWPAN as a foundation, while leaving application protocols above it.',name:'Thread',role:'Networking suite',detail:'Thread spans several networking responsibilities. It is not an application protocol and not a peer substitute for TCP.'}
];
function renderNetworkDetective(){const host=document.getElementById('networkDetective');host.innerHTML=networkCards.map(c=>{const d=state.networkDetective[c.id]||{};return `<article class="detective-card"><span class="case-kicker">Unknown ${c.id.toUpperCase()}</span><p class="detective-clue">${c.clue}</p><div class="role-options">${['Link','Adaptation','Network','Transport','Application','Networking suite'].map(r=>`<button class="role-option ${d.role===r?'selected':''}" data-net="${c.id}" data-role="${r}" type="button">${r}</button>`).join('')}</div>${d.role?`<button class="btn" data-reveal-net="${c.id}" type="button">Reveal name</button>`:''}${d.revealed?`<div class="reveal-box"><b>${c.name} · ${c.role}</b><span>${c.detail}</span></div>`:''}</article>`}).join('');host.querySelectorAll('[data-net]').forEach(b=>b.onclick=()=>{state.networkDetective[b.dataset.net]=state.networkDetective[b.dataset.net]||{};state.networkDetective[b.dataset.net].role=b.dataset.role;save();renderNetworkDetective();updateGates()});host.querySelectorAll('[data-reveal-net]').forEach(b=>b.onclick=()=>{state.networkDetective[b.dataset.revealNet].revealed=true;save();renderNetworkDetective();updateGates()})}

const appPatterns=[
{id:'mqtt',title:'Many consumers need telemetry',copy:'Sensors produce updates; storage, dashboard and analytics may all be interested without the sensor knowing each consumer.',options:['Direct request/response','Brokered publish/subscribe','One long byte stream'],answer:'Brokered publish/subscribe',name:'MQTT',detail:'MQTT is a client/server publish-subscribe messaging protocol with topics and QoS. It expects an ordered, lossless transport; TCP is a common fit.'},
{id:'coap',title:'Read or observe a constrained resource',copy:'A client wants /sensors/17/co2 and may want updates when that resource changes.',options:['Resource request/response / observe','Brokered publish/subscribe','Raw frame exchange'],answer:'Resource request/response / observe',name:'CoAP',detail:'CoAP is a RESTful application protocol for constrained nodes/networks. Canonically it exchanges request/response messages over datagram transport such as UDP; Confirmable messages add optional reliability.'},
{id:'http',title:'Expose a web-facing service API',copy:'A dashboard or external service accesses resources through familiar web semantics.',options:['HTTP-style request/response','Local MAC frames only','Mesh routing protocol'],answer:'HTTP-style request/response',name:'HTTP',detail:'HTTP is an application-level request/response protocol. Its transport depends on the HTTP version; it is not synonymous with TCP.'}
];
function renderAppPatterns(){const host=document.getElementById('appPatternGrid');host.innerHTML=appPatterns.map(p=>{const d=state.appPatterns[p.id]||{};return `<article class="pattern-card"><span class="case-kicker">Service need</span><h3>${p.title}</h3><p class="pattern-question">${p.copy}</p><div class="pattern-options">${p.options.map(o=>`<button class="pattern-option ${d.choice===o?'selected':''}" data-app="${p.id}" data-choice="${o}" type="button">${o}</button>`).join('')}</div>${d.choice?`<button class="btn" data-reveal-app="${p.id}" type="button">Reveal protocol</button>`:''}${d.revealed?`<div class="protocol-reveal"><b>${p.name}</b><p>${p.detail}</p></div>`:''}</article>`}).join('');host.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>{state.appPatterns[b.dataset.app]=state.appPatterns[b.dataset.app]||{};state.appPatterns[b.dataset.app].choice=b.dataset.choice;save();renderAppPatterns();updateGates()});host.querySelectorAll('[data-reveal-app]').forEach(b=>b.onclick=()=>{state.appPatterns[b.dataset.revealApp].revealed=true;save();renderAppPatterns();updateGates()})}
const claims=[['Thread and TCP are alternatives at the same layer.','False','Thread is a networking suite; TCP is a transport protocol.'],['MQTT and Wi-Fi can appear in the same end-to-end stack.','True','They solve different responsibilities.'],['UDP guarantees ordered delivery.','False','UDP does not guarantee delivery, order or duplicate protection.'],['CoAP can implement reliability even when using UDP.','True','Confirmable CoAP messages provide optional message-layer reliability.']];
function renderClaims(){document.getElementById('claimGrid').innerHTML=claims.map((c,i)=>{const v=state.claims[i];return `<div class="claim"><strong>${c[0]}</strong><div class="claim-options"><button data-claim="${i}" data-v="True" class="${v==='True'?'active':''}">True</button><button data-claim="${i}" data-v="False" class="${v==='False'?'active':''}">False</button></div>${v?`<div class="claim-feedback">${v===c[1]?'✓':'Reconsider:'} ${c[2]}</div>`:''}</div>`}).join('');document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{state.claims[b.dataset.claim]=b.dataset.v;save();renderClaims();updateGates()})}


const interopFieldDefs=[
['phenomenon','What is measured?','CO₂ concentration, temperature, humidity…'],['unit','Unit','ppm, °C, %RH…'],['sensor','Sensor / source identifier','Which device or logical source produced it?'],['time','Timestamp','When was the observation made?'],['location','Location / context','Where or in which room / asset?'],['quality','Quality / validity','Is the value valid, stale, estimated or uncertain?']
];
const namingDefs=[['2001:db8::17','Network address'],['5683','Transport port'],['sensor-b2-r204.example','Hostname'],['/sensors/co2','Resource path / URI component'],['campus/building2/co2','MQTT topic']];
const namingTypes=['Network address','Transport port','Hostname','Resource path / URI component','MQTT topic'];
function renderInterop(){const f=new Set(state.interopFields||[]);const host=document.getElementById('interopFields');if(host){host.innerHTML=interopFieldDefs.map(([id,n,c])=>`<button type="button" class="interop-field ${f.has(id)?'active':''}" data-interop-field="${id}"><strong>${n}</strong><span>${c}</span></button>`).join('');host.querySelectorAll('[data-interop-field]').forEach(b=>b.onclick=()=>{const s=new Set(state.interopFields||[]);s.has(b.dataset.interopField)?s.delete(b.dataset.interopField):s.add(b.dataset.interopField);state.interopFields=[...s];save();renderInterop();updateGates()})}const ng=document.getElementById('namingGrid');if(ng){ng.innerHTML=namingDefs.map(([v,correct],i)=>`<label class="naming-item"><code>${v}</code><select data-naming="${i}"><option value="">Classify…</option>${namingTypes.map(x=>`<option ${state.naming?.[i]===x?'selected':''}>${x}</option>`).join('')}</select></label>`).join('');ng.querySelectorAll('select').forEach(s=>s.onchange=()=>{state.naming=state.naming||{};state.naming[s.dataset.naming]=s.value;save();updateGates()})}const ta=document.getElementById('interopRationale');if(ta){ta.value=state.interopRationale||'';ta.oninput=e=>{state.interopRationale=e.target.value;save();updateGates()}}}
function interopNamingCorrect(){return namingDefs.every((x,i)=>state.naming?.[i]===x[1])}
const protocolTiles=[
{id:'wifi',name:'Wi-Fi',layer:'link',note:'local access'}, {id:'154',name:'IEEE 802.15.4',layer:'link',note:'constrained local link'},
{id:'6lowpan',name:'6LoWPAN',layer:'adaptation',note:'IPv6 adaptation'}, {id:'none',name:'No adaptation',layer:'adaptation',note:'not always needed'},
{id:'ipv6',name:'IPv6',layer:'network',note:'address + route'}, {id:'tcp',name:'TCP',layer:'transport',note:'ordered reliable stream'}, {id:'udp',name:'UDP',layer:'transport',note:'datagrams'},
{id:'mqtt',name:'MQTT',layer:'application',note:'publish / subscribe'}, {id:'coap',name:'CoAP',layer:'application',note:'resource req/resp'}, {id:'http',name:'HTTP',layer:'application',note:'web req/resp'}
];
const cases={a:{title:'Constrained local sensor',copy:'Battery-powered sensor on a constrained IEEE 802.15.4 network. A local service reads or observes a resource.',expected:{link:'154',adaptation:'6lowpan',network:'ipv6',transport:'udp',application:'coap'}},b:{title:'Gateway to cloud telemetry',copy:'A powered gateway already has Wi-Fi connectivity, and this exercise assumes IPv6 end-to-end to a brokered cloud service.',expected:{link:'wifi',adaptation:'none',network:'ipv6',transport:'tcp',application:'mqtt'}}};
function placeProto(pid,layer,c){const tile=protocolTiles.find(x=>x.id===pid);if(!tile)return;if(tile.layer!==layer)return toast(`${tile.name} solves ${tile.layer}, not ${layer}`);state.compositions[c]=state.compositions[c]||{};state.compositions[c][layer]=pid;selectedProto=null;state.composeValid[c]=false;save();renderComposer();updateGates()}
function renderComposer(){const c=state.composeCase,d=state.compositions[c]||{};document.querySelectorAll('.composer-tab').forEach(b=>b.classList.toggle('active',b.dataset.composeCase===c));document.getElementById('caseBrief').innerHTML=`<b>${cases[c].title}</b><br>${cases[c].copy}`;const used=new Set(Object.values(d));document.getElementById('protocolPalette').innerHTML=protocolTiles.filter(t=>!used.has(t.id)).map(t=>`<div class="protocol-tile ${selectedProto===t.id?'selected':''}" draggable="true" data-proto="${t.id}">${t.name}<small>${t.note}</small></div>`).join('');document.getElementById('protocolStack').innerHTML=layers.map(([id,name])=>{const pid=d[id],t=protocolTiles.find(x=>x.id===pid);return `<div class="protocol-slot" data-proto-layer="${id}"><strong>${name}</strong><div class="protocol-drop">${t?`<div class="protocol-tile" data-remove-proto="${id}">${t.name}<small>${t.note}</small></div>`:'Drop protocol here'}</div></div>`}).join('');document.querySelectorAll('[data-proto]').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.proto);x.onclick=()=>{selectedProto=selectedProto===x.dataset.proto?null:x.dataset.proto;renderComposer()}});document.querySelectorAll('[data-proto-layer]').forEach(s=>{s.ondragover=e=>{e.preventDefault();s.classList.add('dragover')};s.ondragleave=()=>s.classList.remove('dragover');s.ondrop=e=>{e.preventDefault();s.classList.remove('dragover');placeProto(e.dataTransfer.getData('text/plain'),s.dataset.protoLayer,c)};s.onclick=e=>{if(e.target.closest('[data-remove-proto]'))return;if(selectedProto)placeProto(selectedProto,s.dataset.protoLayer,c)}});document.querySelectorAll('[data-remove-proto]').forEach(x=>x.onclick=()=>{delete state.compositions[c][x.dataset.removeProto];state.composeValid[c]=false;save();renderComposer();updateGates()});const fb=document.getElementById('composerFeedback');fb.className='composer-feedback '+(state.composeValid[c]?'good':'');fb.textContent=state.composeValid[c]?'Composition checked: technically coherent for the stated scenario.':'Build the stack, then check it.'}
document.querySelectorAll('[data-compose-case]').forEach(b=>b.onclick=()=>{state.composeCase=b.dataset.composeCase;save();renderComposer()});document.getElementById('checkStack').onclick=()=>{const c=state.composeCase,got=state.compositions[c]||{},exp=cases[c].expected;const complete=layers.every(([id])=>got[id]);if(!complete)return toast('Complete all five responsibilities first');const ok=Object.keys(exp).every(k=>got[k]===exp[k]);state.composeValid[c]=ok;save();renderComposer();updateGates();if(!ok)toast('Valid pieces can still form the wrong composition — inspect the assumptions')};
const campusChoices=['Brokered pub/sub for telemetry + direct resource exchange where needed','One application protocol for every flow','Hybrid / different patterns for different flows','Not enough information yet'];
function renderCampus(){document.getElementById('campusOptions').innerHTML=campusChoices.map(c=>`<button type="button" class="campus-option ${state.campusChoice===c?'active':''}" data-campus="${c}">${c}</button>`).join('');document.querySelectorAll('[data-campus]').forEach(b=>b.onclick=()=>{state.campusChoice=b.dataset.campus;save();renderCampus();updateGates()});document.getElementById('campusRationale').value=state.campusRationale||'';document.getElementById('campusRationale').oninput=e=>{state.campusRationale=e.target.value;save();updateGates()}}

const deliveryCases=[
{id:'ambient',k:'A',title:'Ambient telemetry',copy:'A one-minute CO₂ sample may occasionally be lost; a newer sample will soon replace it.',answer:'Best effort / occasional loss acceptable'},
{id:'alarm',k:'B',title:'Critical alert',copy:'The alert should eventually reach the service. A duplicate notification is tolerable if it is recognized.',answer:'At least once delivery'},
{id:'command',k:'C',title:'Ventilation command',copy:'The physical operation must not happen twice just because a sender retried after a timeout.',answer:'No duplicate operation effect'},
{id:'offline',k:'D',title:'Temporarily offline consumer',copy:'A consumer disconnects briefly but should receive relevant information after reconnecting.',answer:'Survive temporary disconnection'}
];
const deliveryGuarantees=['Best effort / occasional loss acceptable','At least once delivery','No duplicate operation effect','Survive temporary disconnection'];
const deliveryZones=[['transport','Transport'],['appProtocol','Application protocol'],['application','Application / system semantics'],['intermediary','Intermediary / session state'],['physical','Physical / control loop']];
const deliveryMechanisms=[
{id:'tcp',name:'TCP retransmission + in-order byte stream',note:'loss recovery + ordering',zone:'transport'},
{id:'mqtt',name:'MQTT QoS acknowledgement flows',note:'QoS-specific acknowledgements',zone:'appProtocol'},
{id:'coap',name:'CoAP CON / ACK + retransmission',note:'confirmation + retry',zone:'appProtocol'},
{id:'buffer',name:'Broker/session buffering or store-and-forward',note:'retain / replay across absence',zone:'intermediary'},
{id:'idem',name:'Idempotency · deduplication · correlation ID',note:'prevent a duplicate side effect',zone:'application'},
{id:'feedback',name:'Measured physical-state feedback',note:'observe the resulting state',zone:'physical'}
];
function placeDeliveryMechanism(id,zone){if(!deliveryMechanisms.find(m=>m.id===id))return;state.deliveryMechanisms=state.deliveryMechanisms||{};state.deliveryMechanisms[id]=zone;selectedDeliveryMechanism=null;save();renderDeliverySemantics();updateGates()}
function renderDeliverySemantics(){const gh=document.getElementById('guaranteeCaseGrid');if(gh){gh.innerHTML=deliveryCases.map(c=>`<article class="guarantee-case"><span class="case-kicker">Case ${c.k}</span><h3>${c.title}</h3><p>${c.copy}</p><div class="guarantee-options">${deliveryGuarantees.map(g=>`<button type="button" class="guarantee-option ${state.deliveryCases?.[c.id]===g?'active':''}" data-delivery-case="${c.id}" data-guarantee="${g}">${g}</button>`).join('')}</div></article>`).join('');gh.querySelectorAll('[data-delivery-case]').forEach(b=>b.onclick=()=>{state.deliveryCases=state.deliveryCases||{};state.deliveryCases[b.dataset.deliveryCase]=b.dataset.guarantee;save();renderDeliverySemantics();updateGates()})}
const placed=new Set(Object.keys(state.deliveryMechanisms||{}));const ph=document.getElementById('mechanismPalette');if(ph){ph.innerHTML=deliveryMechanisms.filter(m=>!placed.has(m.id)).map(m=>`<div class="mechanism-chip ${selectedDeliveryMechanism===m.id?'selected':''}" draggable="true" data-delivery-mech="${m.id}">${m.name}<span>${m.note}</span></div>`).join('');ph.querySelectorAll('[data-delivery-mech]').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.deliveryMech);x.onclick=()=>{selectedDeliveryMechanism=selectedDeliveryMechanism===x.dataset.deliveryMech?null:x.dataset.deliveryMech;renderDeliverySemantics()}})}
const zh=document.getElementById('guaranteeZones');if(zh){zh.innerHTML=deliveryZones.map(([id,name])=>`<div class="guarantee-zone" data-delivery-zone="${id}"><strong>${name}</strong><div class="guarantee-zone-items">${deliveryMechanisms.filter(m=>state.deliveryMechanisms?.[m.id]===id).map(m=>`<span class="placed-mechanism" data-unplace-delivery="${m.id}">${m.name}</span>`).join('')}</div></div>`).join('');zh.querySelectorAll('[data-delivery-zone]').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('dragover')};z.ondragleave=()=>z.classList.remove('dragover');z.ondrop=e=>{e.preventDefault();z.classList.remove('dragover');placeDeliveryMechanism(e.dataTransfer.getData('text/plain'),z.dataset.deliveryZone)};z.onclick=e=>{if(e.target.closest('[data-unplace-delivery]'))return;if(selectedDeliveryMechanism)placeDeliveryMechanism(selectedDeliveryMechanism,z.dataset.deliveryZone)}});zh.querySelectorAll('[data-unplace-delivery]').forEach(x=>x.onclick=()=>{delete state.deliveryMechanisms[x.dataset.unplaceDelivery];save();renderDeliverySemantics();updateGates()})}
const ta=document.getElementById('deliveryRationale');if(ta){ta.value=state.deliveryRationale||'';ta.oninput=e=>{state.deliveryRationale=e.target.value;save();updateGates()}}}
function deliverySnapshot(){const cases=deliveryCases.map(c=>`${c.k}: ${state.deliveryCases?.[c.id]||'—'}`).join(' · ');const mechanisms=deliveryMechanisms.map(m=>`${m.name} → ${deliveryZones.find(z=>z[0]===state.deliveryMechanisms?.[m.id])?.[1]||'—'}`).join('<br>');return `<div><b>Service guarantees</b><span>${cases}</span></div><div><b>Mechanism scope</b><span>${mechanisms}</span></div>`}

const incidents=[['loss','Packet loss','Sam reports that a telemetry datagram disappears on a degraded path.'],['duplicate','Duplicate action','Sam reports that one ventilation command is processed twice after a retry.'],['broker','Broker unavailable','Leila reports that devices can reach the network, but the MQTT broker is unavailable.'],['sleep','Sleeping sensor','Sam reports that a sleepy node is offline when a direct request arrives.']];
function renderIncidents(){document.getElementById('incidentGrid').innerHTML=incidents.map(i=>`<button class="incident ${state.incident===i[0]?'active':''}" data-incident="${i[0]}" type="button"><b>${i[1]}</b><span>${i[2]}</span></button>`).join('');document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{state.incident=b.dataset.incident;save();renderIncidents();updateGates()});[['failureMeaning','failureMeaning'],['failureLayer','failureLayer'],['failureRevision','failureRevision']].forEach(([id,k])=>{const el=document.getElementById(id);el.value=state[k]||'';el.oninput=e=>{state[k]=e.target.value;save();updateGates()}})}

function updateGates(){const convDone=convoCases.every(c=>['init','recv','reply','time'].every(k=>state.conversations[c.id]?.[k]));document.getElementById('a1Next').disabled=!convDone;document.getElementById('a2Next').disabled=state.actors.filter(Boolean).length<3||state.messages.length<3;const roleDone=responsibilities.every(r=>Object.values(state.stackRoles).some(a=>(a||[]).includes(r.id)));document.getElementById('a3Next').disabled=!roleDone;document.getElementById('a4Next').disabled=!networkCards.every(c=>state.networkDetective[c.id]?.revealed);document.getElementById('a5Next').disabled=!appPatterns.every(p=>state.appPatterns[p.id]?.revealed)||Object.keys(state.claims).length<4;document.getElementById('a6Next').disabled=!((state.interopFields||[]).length>=4&&interopNamingCorrect()&&(state.interopRationale||'').trim().length>30);document.getElementById('a7Next').disabled=!(state.composeValid.a&&state.composeValid.b&&state.campusChoice&&state.campusRationale.trim().length>15);document.getElementById('a8Next').disabled=!(deliveryCases.every(c=>state.deliveryCases?.[c.id])&&deliveryMechanisms.every(m=>state.deliveryMechanisms?.[m.id])&&(state.deliveryRationale||'').trim().length>30);document.getElementById('a9Next').disabled=!(state.incident&&state.failureMeaning.trim().length>8&&state.failureLayer.trim().length>8&&state.failureRevision.trim().length>8);updateStopNextButtons()}
function renderSnapshots(){const s1=document.getElementById('stop1Snapshot');if(s1)s1.innerHTML=convoCases.map(c=>{const d=state.conversations[c.id]||{};return `<div><b>${c.title}</b><span>${d.init||'—'} · ${d.recv||'—'} · reply ${d.reply||'—'} · ${d.time||'—'}</span></div>`}).join('');const s2=document.getElementById('stop2Snapshot');if(s2)s2.innerHTML=`<b>${state.choreoScenario||'telemetry'} choreography</b>${state.messages.map(m=>`<div>${m.from} → ${m.to} · ${m.label}</div>`).join('')}`;const s3=document.getElementById('stop3Snapshot');if(s3)s3.innerHTML=layers.map(([id,n])=>`<div><b>${n}</b><span>${(state.stackRoles[id]||[]).map(rid=>responsibilities.find(r=>r.id===rid)?.text).join(' · ')||'—'}</span></div>`).join('');const s6=document.getElementById('stop6Snapshot');if(s6)s6.innerHTML=`<div><b>Payload fields selected</b><span>${(state.interopFields||[]).map(id=>interopFieldDefs.find(x=>x[0]===id)?.[1]).filter(Boolean).join(' · ')||'—'}</span></div><div><b>Identifier distinctions</b><span>${interopNamingCorrect()?'Network · port · hostname · resource · topic':'Still being classified'}</span></div>`;const s7=document.getElementById('stop7Snapshot');if(s7)s7.innerHTML=`<div><b>Case A</b><span>${stackText('a')}</span></div><div><b>Case B</b><span>${stackText('b')}</span></div><div><b>Campus position</b><span>${state.campusChoice||'—'}</span></div>`;const s8=document.getElementById('stop8Snapshot');if(s8)s8.innerHTML=deliverySnapshot();const s9=document.getElementById('stop9Snapshot');if(s9)s9.innerHTML=`<div><b>Incident</b><span>${incidents.find(x=>x[0]===state.incident)?.[1]||'—'}</span></div><div><b>Failed guarantee</b><span>${state.failureMeaning||'—'}</span></div><div><b>Mechanism / scope</b><span>${state.failureLayer||'—'}</span></div><div><b>Revision</b><span>${state.failureRevision||'—'}</span></div>`}
function stackText(c){const d=state.compositions[c]||{};return layers.slice().reverse().map(([id])=>protocolTiles.find(t=>t.id===d[id])?.name||'—').join(' → ')}
function renderDrawer(){const body=document.getElementById('drawerBody');if(!body)return;body.innerHTML=`<section class="drawer-section"><b>Interaction map</b><p>${Object.keys(state.conversations).length}/4 situations described.</p></section><section class="drawer-section"><b>Message choreography</b><p>${state.messages.length} messages · ${state.actors.filter(Boolean).length} actors.</p></section><section class="drawer-section"><b>Interoperability</b><p>${(state.interopFields||[]).length}/6 payload fields identified · ${interopNamingCorrect()?'identifier map complete':'identifier map incomplete'}.</p></section><section class="drawer-section"><b>Stack A</b><p>${stackText('a')}</p></section><section class="drawer-section"><b>Stack B</b><p>${stackText('b')}</p></section><section class="drawer-section"><b>Campus position</b><p>${state.campusChoice||'Not committed yet'}</p></section><section class="drawer-section"><b>Delivery semantics</b><p>${Object.keys(state.deliveryCases||{}).length}/4 service guarantees · ${Object.keys(state.deliveryMechanisms||{}).length}/6 mechanisms scoped.</p></section>`}
const drawer=document.getElementById('stackDrawer'),scrim=document.getElementById('drawerScrim');document.getElementById('stackBtn').onclick=()=>{closeFieldGuide();drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');scrim.hidden=false};function closeDrawer(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');scrim.hidden=true}document.getElementById('drawerClose').onclick=closeDrawer;scrim.onclick=closeDrawer;
const fieldGuideDrawer=document.getElementById('fieldGuideDrawer'),fieldGuideScrim=document.getElementById('fieldGuideScrim');function closeFieldGuide(){fieldGuideDrawer?.classList.remove('open');fieldGuideDrawer?.setAttribute('aria-hidden','true');if(fieldGuideScrim)fieldGuideScrim.hidden=true}document.getElementById('fieldGuideBtn').onclick=()=>{closeDrawer();fieldGuideDrawer.classList.add('open');fieldGuideDrawer.setAttribute('aria-hidden','false');fieldGuideScrim.hidden=false};document.getElementById('closeFieldGuide').onclick=closeFieldGuide;fieldGuideScrim.onclick=closeFieldGuide;


const recallPrompts=[
 {id:'thread',q:'Why is Thread not the same kind of object as TCP?',a:'Thread is an IPv6-based IoT networking suite spanning several networking responsibilities; TCP is a transport protocol that provides a reliable in-order byte stream.'},
 {id:'coexist',q:'Why can MQTT and Wi-Fi coexist without competing?',a:'They solve different responsibilities: MQTT defines application-level publish/subscribe messaging, while Wi-Fi provides local network access/link functions.'},
 {id:'meaning',q:'Why is a delivered JSON payload not automatically semantically interoperable?',a:'Delivery proves the bytes arrived, not that the receiver shares the phenomenon, unit, source, timestamp, identifiers or data model needed to interpret them.'},
 {id:'qos',q:'What is the difference between TCP reliable delivery and MQTT message QoS?',a:'TCP guarantees a reliable in-order byte stream between transport endpoints. MQTT QoS defines delivery semantics for MQTT messages above that transport, with its own acknowledgement flows and scope.'},
 {id:'duplicate',q:'Why can at-least-once message delivery create a duplicate application effect?',a:'At-least-once permits duplicate message delivery. Without idempotence, deduplication or operation IDs, a repeated message can trigger the same application or physical action twice.'},
 {id:'physical',q:'What evidence would confirm that a physical command actually took effect?',a:'Measured physical-state feedback or another observation of the resulting state. A transport/application acknowledgement alone does not prove the actuator or physical process succeeded.'}
];
function renderMemoryLock(){const host=document.getElementById('memoryLock');if(!host)return;const done=recallPrompts.filter(x=>state.recall?.[x.id]).length;host.innerHTML=`<div class="memory-head"><span class="memory-icon">↺</span><div><strong>30-second memory lock</strong><small>Say the answer before revealing it.</small></div></div><div class="memory-grid">${recallPrompts.map((x,i)=>{const shown=!!state.recall?.[x.id];return `<article class="memory-card ${shown?'revealed':''}"><span class="memory-number">${i+1}</span><strong>${x.q}</strong>${shown?`<p>${x.a}</p>`:`<button type="button" class="recall-reveal" data-recall="${x.id}">Reveal after answering</button>`}</article>`}).join('')}</div><div class="memory-progress">${done} / ${recallPrompts.length} revealed</div>`;host.querySelectorAll('[data-recall]').forEach(b=>b.onclick=()=>{state.recall={...(state.recall||{}),[b.dataset.recall]:true};save();renderMemoryLock()});const synth=document.getElementById('sessionSynthesis');if(synth)synth.hidden=done<recallPrompts.length}

function exportSession(){const blob=new Blob([JSON.stringify({course:'IoT Systems Design',session:'Session 2',exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='iot-session2-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800)}document.getElementById('exportBtn').onclick=exportSession;const finishExport=document.getElementById('finishExport');if(finishExport)finishExport.onclick=exportSession;document.getElementById('importInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result),candidate=parsed.data||parsed;state={...defaultState(),...candidate};state.maxUnlockedScreen=Math.max(Number(state.maxUnlockedScreen)||0,Number(state.screen)||0,ACTIVITY_ENTRY[Math.min(Number(state.frontier)||0,8)]||0);save();renderAll();show(Math.min(Number(state.screen)||0,screens.length-1),false);toast('Imported')}catch{toast('Invalid file')}};r.readAsText(f)};document.getElementById('resetBtn').onclick=()=>{if(confirm('Reset all Session 2 work on this browser?')){state=defaultState();save();renderAll();show(0,false)}};
function renderAll(){renderConversations();renderChoreo();renderRoleStack();renderNetworkDetective();renderAppPatterns();renderClaims();renderInterop();renderComposer();renderCampus();renderDeliverySemantics();renderIncidents();renderSnapshots();renderDrawer();renderStopRitual();renderFieldGuide();renderMemoryLock();renderAdaptiveDepth();renderExpertProgress();updateGates();renderStepper();renderHistoryNav()}
renderAll();show(Math.min(state.screen,screens.length-1),false);
})();